{"script":"() => {
  // Find the 3.0 to 3.9 qt filter link and get its details
  const filter = document.querySelector('a[aria-label="Apply 3.0 to 3.9 qt filter to narrow results"]');
  if (filter) {
    filter.scrollIntoView({behavior: 'instant', block: 'center'});
    return {found: true, href: filter.href, text: filter.textContent.trim()};
  }
  return {found: false};
}"}

